public class Test {
    public static void main(String[] a) {
        if (!(WordCounter.countWords(null) == 0)) throw new AssertionError("null text");
        if (!(WordCounter.countWords("  the quick  fox ") == 3)) throw new AssertionError("normal");
        if (!(WordCounter.countWords("   ") == 0)) throw new AssertionError("blank");
        System.out.println("PASS");
    }
}
